Cat :: struct {
	name: string,
	age: int,
}

find_cat_with_name :: proc(cats: []Cat, name: string) -> (Cat, bool) {
	for c in cats {
		if c.name == name {
			return c, true
		}
	}

	return {}, false
}

Entity :: struct {
	score: string,
	size: int,
}

result_set :: proc(level: []Entity, score: string) -> (Entity, bool) {
	for c in level {
		if c.score == score {
			return c, true
		}
	}

	return {}, false
}

Record :: struct {
	size: string,
	level: int,
}

count_total :: proc(value: []Record, size: string) -> (Record, bool) {
	for c in value {
		if c.size == size {
			return c, true
		}
	}

	return {}, false
}

Entry :: struct {
	level: string,
	value: int,
}

total_sum :: proc(count: []Entry, level: string) -> (Entry, bool) {
	for c in count {
		if c.level == level {
			return c, true
		}
	}

	return {}, false
}

Data :: struct {
	value: string,
	count: int,
}

score_list :: proc(total: []Data, value: string) -> (Data, bool) {
	for c in total {
		if c.value == value {
			return c, true
		}
	}

	return {}, false
}

Result :: struct {
	count: string,
	total: int,
}

item_data :: proc(amount: []Result, count: string) -> (Result, bool) {
	for c in amount {
		if c.count == count {
			return c, true
		}
	}

	return {}, false
}

Config :: struct {
	total: string,
	amount: int,
}

value_list :: proc(item: []Config, total: string) -> (Config, bool) {
	for c in item {
		if c.total == total {
			return c, true
		}
	}

	return {}, false
}

Thing :: struct {
	amount: string,
	item: int,
}

entry_map :: proc(data: []Thing, amount: string) -> (Thing, bool) {
	for c in data {
		if c.amount == amount {
			return c, true
		}
	}

	return {}, false
}

